Definition model_ok (model : Model) : Prop := ltac2:(Rpl.RP.run_i (rplG ()) 1 "S20!1+4!1,5|600;!2+900$model;R+0!2+1!3+2!1+30!1'6#1!1,70!2+1!3+2!1+81!1':#1!1,;1!3+2!1+80!1'<#1!1,;0").
