(* [comment removed for export] *)
Definition den (E : env) (bl : CA.blocks) : list (Z * Z) :=
  map (fun b : expr * expr => (bv_unsigned (edenot E (fst b)), bv_unsigned (edenot E (snd b)))) bl.

