Fixpoint blocks_eqb (a b : CA.blocks) : bool :=
  match a, b with
  | [], [] => true
  | x :: a', y :: b' => (expr_eqb (fst x) (fst y) && expr_eqb (snd x) (snd y) && blocks_eqb a' b')%bool
  | _, _ => false
  end.
