Hypothesis IMG_LO_eq : hl_img_lo L = IMG_LO.
Hypothesis IMG_HI_eq : hl_img_hi L = IMG_HI.

Definition nonempty (cells : list kentry) (m : expr) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S80|10;!1,^W,_<!1,^W|^B7fffffffffffffff;!3,cR#212!3,cR#412!2'^D!2'f\#54!2'g0#54!3,cR#512!2'^D!2'f\#66!2'g0#66$cells;R!1+8+bP$m;R+?-?RN$m;R+?+A#18$z;R+I!2'C!2'eN,^?#1!2'eN#1!2'a?!1,^W0!1,^W|600;$n;R+=!2'^D!2'f\#33!2'g0#33$op;R+eU$a;R+?$b;R+?5$op;R+eU$a;R+?$b;R+?5$op;R+eV$a;R+?$b;R+?5$op;R+eV$a;R+?$b;R+?5$sx;R+A$lo;R+=$n;R+=$e;R+?7$sx;R+A$k;R+=$i;R+I$n;R+=7").   (* [comment removed for export] *)
Definition apart_regs (BL : CA.blocks) : list SGP.region := CH.stack_reg d :: CH.hd_crs d ++ CH.hd_wrs d ++ CH.blk_regs BL.
Definition fresh_fact_ok (cells : list kentry) (nx : nat) (BLi : CA.blocks) (a0v : nat) (n : expr) (X : kentry) : bool :=
  match X with
  | KRange (EVar v) lo hi => (Nat.eqb v a0v && Z.eqb lo 4096 && Z.eqb hi 140737488355328)%bool
  | KAlign (EVar v) m => (Nat.eqb v a0v && Z.eqb m 16)%bool
  | KUnk (SA (EVar v) 0) m | KWr (SA (EVar v) 0) m => (Nat.eqb v a0v && expr_eqb m n)%bool
  | KDisj (SA (EVar v) 0) m (SA b o) m2 =>
      (Nat.eqb v a0v && expr_eqb m n &&
       (if (expr_eqb b (ELit 0) && Z.eqb o IMG_LO && expr_eqb m2 (ELit (IMG_HI - IMG_LO)))%bool then true
        else if (APC.expr_vars_lt nx b && APC.expr_vars_lt nx m2)%bool then (if nonempty cells m2 then CH.within cells (apart_regs BLi) b o m2 else false) else false))%bool   (* [comment removed for export] *)
  | _ => false
  end.

