Lemma hpres_know : forall E M M' BLk LBk kn scr c Wc wregs ks,
  env_agree NF E0 E -> blocks_in_range (den E BLk ++ LBrest) -> incl (den E BLk ++ LBrest) LBk ->
  c <= 0 -> 0 <= scr -> - SCR <= c - scr ->
  (forall w a, In w Wc -> L5.in_rng w a -> exists r, In r wregs /\ in_reg E r a) ->
  know_ok (hl_segs L) E M kn -> know_ok (hl_segs L) E M ks -> forallb (keepc_chk kn scr c BLk wregs) ks = true ->
