Record common_facts_x (scr : Z) (ng : nat) (c : CC.cutpoint) (ps : SR.post_spec) (cj : CC.cutpoint) (ci : cinfo) (i : nat) (E E' : env) (R' : bvmap 5 word) (M' : mem) (model : Model) : Prop := CFX {
  cx_amb : heap_amb i E M' model;
  cx_regs : regs_ok E' (ci_regs ci) R';
  cx_regs_eq : ci_regs ci = CA.ps_reglist ps;
  cx_vars : APC.sr_vars_lt (ci_nx ci) (ci_regs ci) = true /\ APC.kn_vars_lt (ci_nx ci) (SR.ps_cells ps) = true /\ (CC.cp_nx c <= ci_nx ci)%nat
            /\ (NF <= CC.cp_nx c)%nat /\ CC.cp_nx cj = (ci_nx ci + ng + APC.NCS)%nat;
  cx_know : know_ok (hl_segs L) E' M' (SR.ps_cells ps);
  cx_ra : getr R' 1%bv = Z_to_bv 64 (CC.cp_pc cj) /\ L5.ra_ok (CC.cp_pc cj);
  cx_sp : getr R' 2%bv = Z_to_bv 64 (sp0 + ci_csp ci) /\ ci_csp ci <= 0 /\ 0 <= scr /\ - SCR <= ci_csp ci - scr;
  cx_stk : L5C.stk (hl_sptop L) M' (sp0 + ci_csp ci) scr;
  cx_tp : getr R' 4%bv = Z_to_bv 64 (hl_tp L);
  cx_agE' : env_agree NF E0 E';
  cx_den : den E' (nth i BLS []) = den E (nth i BLS []);
  cx_meas : forall E2, env_agree (ci_nx ci) E' E2 -> CC.meas cj E2 < CC.meas c E
}.

Lemma common_sound_x : forall scr ng i c ps cj ci E R M model E' R' M',
  common_chk_x scr ng c ps cj (nth i BLS []) = Some ci ->
  CC.At (hl_segs L) c E R M -> heap_amb i E M model -> env_agree (CC.cp_nx c) E E' -> CC.leaf_facts (hl_segs L) c ps E' R' M M' ->
  common_facts_x scr ng c ps cj ci i E E' R' M' model.
