Definition blk_in (BLi : CA.blocks) (b : expr * expr) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S10!2+9+?+?$BLi;R'a6$b;R0!3'^G0$b';R0!2'C!2'dL!3'E+?+?#2!3'E+?+?#1!2'dL!3'F+?+?#2!3'F+?+?#1#2").
Definition kept_chk (cells : list kentry) (scr csp : Z) (nx : nat) (BLk : CA.blocks) (wregs : list SGP.region) (X : kentry) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 7 "S00$cells;R!1+8+bP$scr;R+I$csp;R+I$nx;R+=$BLk;R'a6$wregs;R!1+8'bJ$X;R+bP!2'C!2'C!2'eQ#7#1!6'iF#7#6#5#3#2#1!2'fX#4#1").
Definition custom_chk (scr : Z) (ng : nat) (BLk : CA.blocks) (wregs : list SGP.region) (news : list kentry) (a0x : option expr)
           (c : CC.cutpoint) (ps : SR.post_spec) (cj : CC.cutpoint) (BLi : CA.blocks) : option cinfo :=
  match common_chk_x scr ng c ps cj BLi with
  | Some ci =>
      let cells := SR.ps_cells ps in let nx := ci_nx ci in
      let regs1 := APC.sr_fresh (ci_regs ci) APC.caller_saved (nx + ng) in
      if (CA.regs_eqb (CC.cp_regs cj) (match a0x with Some e => sr_upd regs1 10 e | None => regs1 end)
          && blocks_vars_lt nx BLk && forallb (blk_in BLi) BLk
          && forallb (fun X => if CC.has_cell news X then true else kept_chk cells scr (ci_csp ci) nx BLk wregs X) (CC.cp_know cj))%bool   (* [comment removed for export] *)
      then Some ci else None
  | None => None
  end.

