Lemma custom_ret : forall scr ng BLk wregs news a0x i c ps j cj ci,
  nth_error CPS j = Some cj -> custom_chk scr ng BLk wregs news a0x c ps cj (nth i BLS []) = Some ci ->
  forall E R M model E' R' M',
    CC.At (hl_segs L) c E R M -> amb3 i E M model -> env_agree (CC.cp_nx c) E E' -> CC.leaf_facts (hl_segs L) c ps E' R' M M' ->
    CC.IH (hl_segs L) CPS amb3 K FPI (CC.meas c E) ->
    common_facts_x scr ng c ps cj ci i E E' R' M' model /\
    forall (fx2 : FPState) R2 M2 model2 ghosts LBk Wc,
      length ghosts = ng -> FPI fx2 ->
      (forall r : reg, r <> 0%bv -> ~ In (ridx r) APC.caller_saved -> getr R2 r = getr R' r) ->
      match a0x with Some e => getr R2 10%bv = edenot (retEx E' (ci_nx ci) ghosts R2) e | None => True end ->
      L5C.hpres L LBk (sp0 + ci_csp ci) scr Wc M' M2 -> incl (den E' BLk ++ LBrest) LBk ->
      (forall w a, In w Wc -> L5.in_rng w a -> exists r, In r wregs /\ in_reg E' r a) ->
      (forall X, In X news -> In X (CC.cp_know cj) -> kentry_ok (hl_segs L) (retEx E' (ci_nx ci) ghosts R2) M2 X) ->
      amb3 j (retEx E' (ci_nx ci) ghosts R2) M2 model2 ->
      srealizes (hl_segs L) SCFG (mkCfg (@mkst fx2 R2 (Z_to_bv 64 (CC.cp_pc cj)) M2 (seg_rom (hl_segs L))) model2) K.
