(* [comment removed for export] *)
Lemma ghost_block_fact : forall E' E2 nx M' M2 BL cells gv ne A n X,
  env_agree NF E0 E' -> know_ok (hl_segs L) E' M' cells ->
  env_agree nx E' E2 -> bv_unsigned (ev E2 gv) = A -> elenZ E2 ne = n ->
