(* [comment removed for export] *)
Definition leaf_chk3 (i : nat) (c : CC.cutpoint) (k : nat) (ps : SR.post_spec) (t : CC.tag) : bool :=
  match t with
  | CC.TGoto j s => goto_amb_chk c (nth i BLS []) (nth j BLS []) s
  | CC.TOther _ => foot_chk c (nth i BLS [])
  end.
Definition heap_chk3 : bool := ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00!3'i4/CPS;/TAGS;'j2").

Lemma leaf_amb3 : heap_chk3 = true -> forall i c k ps pc, is_leaf i c k ps (CC.TOther pc) ->
  forall E E' R R' M M' model, CC.At (hl_segs L) c E R M -> heap_amb i E M model -> env_agree (CC.cp_nx c) E E' ->
    CC.leaf_facts (hl_segs L) c ps E' R' M M' -> heap_amb i E M' model.
